int binarySearch(vector<int>& arr, int target, int lo, int hi) {

    // Base Case 1: Element not found
    if (lo > hi) {
        return -1;
    }

    int mid = lo + (hi - lo) / 2;

    // Base Case 2: Element found
    if (arr[mid] == target) {
        return mid;
    }

    // Shrink and Recurse
    if (arr[mid] < target) {
        return binarySearch(arr, target, mid + 1, hi);
    }

    return binarySearch(arr, target, lo, mid - 1);
}

